ext:mongo.ext:mongo:
db.createCollection('harness_products');
db.harness_products.createIndex({ productId: 1 }, { unique: true });
print('Created harness_products collection with index');

db.harness_products.insertMany([
    { productId: 'PROD-001', name: 'Widget', price: 29.99, inStock: true },
    { productId: 'PROD-002', name: 'Gadget', price: 49.99, inStock: true },
    { productId: 'PROD-003', name: 'Doohickey', price: 19.99, inStock: false }
]);
print('Inserted 3 products');

db.harness_products.updateMany(
    { inStock: false },
    { $set: { status: 'discontinued' } }
);
print('Updated out-of-stock products');
